INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '33a78502-9557-5050-b0c3-6b1c8c649eed', '91964a78-8bcf-5785-8f09-a15e0709035e',
  'Xem xét mã giả sau đây. Giả sử rằng `IntQueue` là một hàng đợi số nguyên. Hàm `fun` thực hiện chức năng gì?

```cpp
void fun(int n) {
    IntQueue q = new IntQueue();
    q.enqueue(0);
    q.enqueue(1);

    for (int i = 0; i < n; i++) {
        int a = q.dequeue();
        int b = q.dequeue();
        q.enqueue(b);
        q.enqueue(a + b);

        print(a);
    }
}
```

Lựa chọn:
- In các số từ 0 đến n - 1
- In các số từ n - 1 về 0
- In n số Fibonacci theo thứ tự đảo ngược
- In các số từ 0 đến n
- In n số Fibonacci đầu tiên', 15
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '2b5094cb-dd9b-5b14-b7b2-1b069cfb70b0', '91964a78-8bcf-5785-8f09-a15e0709035e',
  'Đoạn mã nào sau đây in cây nhị phân theo chiều ngang? Select one:

Lựa chọn:
- A.
```cpp
Queue* q = new Queue();
if (root != NULL) {
    q -> enqueue(root);
}
while (!(q -> isEmpty())) {
    q -> dequeue(p);
    cout << p -> data;
    if (p -> left != NULL) {
        q -> enqueue(p -> left);
    }
    if (p -> right != NULL) {
        q -> enqueue(p -> right);
    }
}
delete q;
```
- B.
```cpp
Queue* q = new Queue();
q -> enqueue(root);
while (!(q -> isEmpty())) {
    q -> dequeue(p);
    cout << p -> data;
    if (p -> left != NULL) {
        q -> enqueue(p -> left);
    }
    if (p -> right != NULL) {
        q -> enqueue(p -> right);
    }
}
delete q;
```
- C.
```cpp
Stack* stack = new Stack();

if (root != NULL) {
    stack -> push(root);
}

while (!(stack -> isEmpty())) {
    stack -> pop(p);
    cout << p -> data;
    if (p -> left != NULL) {
        stack -> push(p -> left);
    }
    if (p -> right != NULL) {
        stack -> push(p -> right);
    }
}

delete stack;
```
- D.
```cpp
Stack* stack = new Stack();
stack -> push(root);

while (!(stack -> isEmpty())) {
    stack -> pop(p);
    cout << p -> data;
    if (p -> left != NULL) {
        stack -> push(p -> left);
    }
    if (p -> right != NULL) {
        stack -> push(p -> right);
    }
}

delete stack;
```', 16
);

